void readSingleImageFrame(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo) {
  if (image && image->scene < image->number_frames - 1) {
    MagickCore::Image *extraFrames = image->next;
    while (extraFrames) {
      MagickCore::Image *next = extraFrames->next;
      extraFrames->previous = NULL;
      extraFrames->next = NULL;
      extraFrames = next;
    }
    image->next = NULL;
    image->number_frames = 1;
  }

  if ((exceptionInfo->severity == UndefinedException) && (image == (MagickCore::Image *) NULL)) {
    DestroyException(exceptionInfo);
    if (!IsEventLogging())
      (void) ThrowMagickException(exceptionInfo, GetMagickModule(), ResourceLimitError, "NoImage", "0", "0", "0");
  }

  ThrowImageException(image, MissingDelegateError, "DelegateFailed");
}

void ReadSingleImage(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo)
{
  if (image != (MagickCore::Image *) NULL)
  {
    if (image->next != (MagickCore::Image *) NULL)
    {
      MagickCore::Image
        *next;

      next = image->next;
      while (next != (MagickCore::Image *) NULL)
      {
        MagickCore::Image
          *temp;

        temp = next;
        next = next->next;
        temp->next = (MagickCore::Image *) NULL;
        (void) DestroyImage(temp);
      }
      image->next = (MagickCore::Image *) NULL;
    }
  }

  if ((exceptionInfo->severity == UndefinedException) && (image == (MagickCore::Image *) NULL))
  {
    (void) exceptionInfo->severity;
    if (!IsEnumeratedExceptionType(UndefinedException))
    {
      (void) ThrowMagickException(exceptionInfo, GetMagickModule(), WarningError, "NoImage", "`%s'", "");
    }
    (void) DestroyException(exceptionInfo);
  }

  ThrowImageException(image,ImageError,"UnableToReadImage");
}

void readSingleImageFrame(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo) {
  if (image != (MagickCore::Image *) NULL) {
    if (image->next != (MagickCore::Image *) NULL) {
      MagickCore::Image *nextImage = image->next;
      MagickCore::Image *lastImage = image;
      while (nextImage != (MagickCore::Image *) NULL) {
        lastImage = nextImage;
        nextImage = lastImage->next;
        lastImage->signature = 0;
        lastImage = (MagickCore::Image *) MagickReallocMemory(lastImage, sizeof(*lastImage));
      }
      image->next = (MagickCore::Image *) NULL;
    }
  }

  if (exceptionInfo->severity == UndefinedException && image == (MagickCore::Image *) NULL) {
    exceptionInfo = (MagickCore::ExceptionInfo *) MagickReallocMemory(exceptionInfo, sizeof(*exceptionInfo));
    if (!IsEventLogging())
      (void) ThrowMagickException(exceptionInfo, GetMagickModule(), WarningError,
        "NullImagePointer", "An error occurred with a null image pointer");
  }

  ThrowImageException(exceptionInfo);
}

void readSingleImageFrame(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo) {
    if (image->next != (MagickCore::Image *) NULL) {
        MagickCore::Image *p = image->next;
        MagickCore::Image *q = image;

        while (p != (MagickCore::Image *) NULL) {
            q = p;
            p = q->next;
            MagickCore::DestroyImage(q);
        }
    }

    if ((exceptionInfo->severity == UndefinedException) && (image == (MagickCore::Image *) NULL)) {
        MagickCore::DestroyException(exceptionInfo);
        if (!IsEventLogging())
            (void) ThrowMagickException(exceptionInfo, GetMagickModule(), WarningError,
                                        "NoImage", "`%s' (%s)", image->filename, "image not found");
    }

    ThrowImageException(image, MissingDelegateError, "DelegateFailed");
}

void ReadImage(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo)
{
  if ((image->columns != 0) && (image->rows != 0))
  {
    if (image->scene != 0)
    {
      size_t
        number_images;

      number_images = 1;
      (void) CloneImage(image, image->columns, image->rows, MagickFalse, exceptionInfo);
      if (image->next != (Image *) NULL)
      {
        Image
          *next;

        next = image->next;
        while (next != (Image *) NULL)
        {
          Image
            *destroy_next;

          destroy_next = next;
          next = next->next;
          destroy_next->reference_count++;
          (void) DestroyImage(destroy_next);
        }
      }
    }
  }
  else
  {
    if (exceptionInfo->severity == UndefinedException)
    {
      (void) DestroyExceptionInfo(exceptionInfo);
      if ((image == (Image *) NULL) && !IsEventLogging())
        (void) ThrowMagickException(exceptionInfo, GetMagickModule(), ResourceLimitError, "NoImage", "Warning");
    }
  }
  ThrowImageException(image, exceptionInfo);
}
